 "content": "def transform(grid):
    """Extend the trailing section of incomplete horizontal foreground bars."""
    if not grid or not grid[0]:
        return [row[:] for row in grid]
    from collections import Counter

    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    active = [r for r, row in enumerate(grid) if any(v != bg for v in row)]
    if not active:
        return out

    def end(r):
        return max((c for c, v in enumerate(grid[r]) if v != bg), default=-1)

    # Repeated equal-height bands: copy the trailing motif of the longer band
    # to its matching row in the shorter band.
    bands = []
    for r in active:
        if not bands or r != bands[-1][-1] + 1:
            bands.append([r])
        else:
            bands[-1].append(r)

    pairs = []
    if len(bands) == 2 and len(bands[0]) == len(bands[1]):
        band_a, band_b = bands
        na = sum(v != bg for r in band_a for v in grid[r])
        nb = sum(v != bg for r in band_b for v in grid[r])
        refs, targets = (band_a, band_b) if na >= nb else (band_b, band_a)
        pairs = [(t, ref) for ref, t in zip(refs, targets)]
    else:
        # Match rows by their foreground pattern, preferring a longer matching row.
        for t in active:
            cand = [r for r in active if end(r) > end(t)]
            if cand:
                ref = max(cand, key=lambda r: (sum(grid[t][c] == grid[r][c] for c in range(end(t)+1)), end(r)))
                pairs.append((t, ref))

    for t, ref in pairs:
        et, er = end(t), end(ref)
        for c in range(et+1, min(len(grid[t]), er+1)):
            if c < len(grid[ref]) and grid[ref][c] != bg:
                out[t][c] = 1
    return out


